    q = Fraction(p_den - p_num, p_den)
    # dp[k] is a dict mapping (s, h) -> weight after k steps, with barrier enforced up to k
    dp = { (0, 0): Fraction(1,1) }
    for k in range(0, N):
        newdp = {}
        for (s, h), w in dp.items():
            # try a miss
            s_m = s
            k1 = k+1
            # Check barrier only for k1 <= N-1
            ok_m = True
            if k1 <= N-1:
                # s_m * u_den <= u_num * k1
                if s_m * u_den > u_num * k1:
                    ok_m = False
            if ok_m:
                h_m = h
                # count equality hit only if k1 <= N-1
                if k1 <= N-1:
                    eq_num = u_num * k1
                    if eq_num % u_den == 0:
                        eq_s = eq_num // u_den
                        if s_m == eq_s:
                            h_m += 1
                newdp[(s_m, h_m)] = newdp.get((s_m, h_m), Fraction(0)) + w * q
            # try a make
            s_s = s + 1
            ok_s = True
            if k1 <= N-1:
                if s_s * u_den > u_num * k1:
                    ok_s = False
            if ok_s:
                h_s = h
                if k1 <= N-1:
                    eq_num = u_num * k1
                    if eq_num % u_den == 0:
                        eq_s2 = eq_num // u_den
                        if s_s == eq_s2:
                            h_s += 1
                newdp[(s_s, h_s)] = newdp.get((s_s, h_s), Fraction(0)) + w * p
        dp = newdp
    # collect only states with s == U*N; no equality count at N
    target_s = (u_num * N) // u_den
    dist = {}
    for (s, h), w in dp.items():
        if s == target_s:
            dist[h] = dist.get(h, Fraction(0)) + w
    return dist

# attempt to sample parameters that yield nontrivial positive probability for some hit count
