    max_hits_possible = (N-1) // u_den
    viable = [h for h, w in dist.items() if w > 0 and 0 < h < max_hits_possible]
    if not viable:
        # if all are 0 or max, allow 1 of them only if probability not trivial
        viable = [h for h, w in dist.items() if w > 0]
    if not viable:
        continue
    hit_upper = rng.choice(viable)
